(function(){
 var dk=document.querySelector('.dock'),h=dk.querySelector('.dh'),st=null,KEY='sjm_dock',auto=true,sv={};
 try{sv=JSON.parse(localStorage.getItem(KEY)||'{}')}catch(e){}
 if(sv.min)dk.classList.add('min');
 if(sv.top!=null)auto=false;
 function side(){return dk.classList.contains('left')?'left':'right'}
 function clamp(t){return Math.max(70,Math.min(innerHeight-dk.offsetHeight-10,t))}
 function place(sd,t){dk.classList.toggle('left',sd==='left');dk.style.top=clamp(t)+'px'}
 function re(){if(!dk.offsetHeight)return;place(side(),auto?(innerHeight-dk.offsetHeight)/2:(parseInt(dk.style.top)||0))}
 function save(){try{localStorage.setItem(KEY,JSON.stringify({side:side(),top:auto?null:parseInt(dk.style.top),min:dk.classList.contains('min')}))}catch(e){}}
 if(sv.side==='left')dk.classList.add('left');
 if(sv.top!=null)dk.style.top=sv.top+'px';
 if(window.ResizeObserver)new ResizeObserver(re).observe(dk);
 addEventListener('resize',re);
 h.addEventListener('pointerdown',function(e){var r=dk.getBoundingClientRect();st={x:e.clientX,y:e.clientY,t:r.top,l:r.left,moved:false};try{h.setPointerCapture(e.pointerId)}catch(x){}});
 h.addEventListener('pointermove',function(e){if(!st)return;var dx=e.clientX-st.x,dy=e.clientY-st.y;if(!st.moved&&Math.abs(dx)+Math.abs(dy)<6)return;st.moved=true;dk.classList.add('drag');dk.style.right='auto';dk.style.left=Math.max(0,Math.min(innerWidth-dk.offsetWidth,st.l+dx))+'px';dk.style.top=clamp(st.t+dy)+'px'});
 function end(){if(!st)return;var s=st;st=null;dk.classList.remove('drag');if(s.moved){auto=false;var cx=dk.getBoundingClientRect().left+dk.offsetWidth/2,t=parseInt(dk.style.top);dk.style.left='';dk.style.right='';place(cx<innerWidth/2?'left':'right',t)}else{dk.classList.toggle('min')}save()}
 h.addEventListener('pointerup',end);h.addEventListener('pointercancel',end);
 h.addEventListener('click',function(e){if(e.detail===0){dk.classList.toggle('min');save()}});
 h.addEventListener('keydown',function(e){var t=parseInt(dk.style.top)||0,k=e.key;if(k==='ArrowUp'||k==='ArrowDown'){auto=false;place(side(),t+(k==='ArrowUp'?-30:30))}else if(k==='ArrowLeft'||k==='ArrowRight'){auto=false;place(k==='ArrowLeft'?'left':'right',t)}else return;e.preventDefault();save()});
})();
