/* float only the element nearest the viewport centre */
function pick(){var els=document.querySelectorAll('.card,.map'),mid=innerHeight/2,best=null,bd=1e9;els.forEach(function(x){var r=x.getBoundingClientRect();if(!r.height||r.bottom<0||r.top>innerHeight)return;var d=Math.abs((r.top+r.bottom)/2-mid);if(d<bd){bd=d;best=x}});els.forEach(function(x){x.classList.toggle('focus',x===best&&bd<innerHeight*.35)})}
var tk=0;function sched(){if(!tk){tk=requestAnimationFrame(function(){tk=0;pick()})}}
addEventListener('scroll',sched,{passive:true});addEventListener('resize',sched);document.addEventListener('click',function(){setTimeout(pick,150)});setTimeout(pick,600);
