document.querySelectorAll('main section').forEach(function(s){so.observe(s)});
/* gate */
function ls(k,v){try{if(v===undefined)return localStorage.getItem(k);localStorage.setItem(k,v)}catch(x){return null}}
function open_(){$('#gate').style.display='none';$('#site').classList.add('show');document.body.style.overflow=''}
var entered=false;try{entered=sessionStorage.getItem('sjm_in')==='1'||ls('sjm_user')}catch(x){}
if(entered)open_();else{document.body.style.overflow='hidden';setTimeout(function(){$('#n').focus()},400)}
function setE(id,eid,msg){$(id).setAttribute('aria-invalid',!!msg);$(eid).textContent=msg||'';return !msg}
$('#gf').addEventListener('submit',function(e){
 e.preventDefault();
 var n=$('#n').value.trim(),p=$('#p').value.trim(),em=$('#e').value.trim();
 var digits=p.replace(/[\s\-()]/g,'').replace(/^(\+91|91|0)(?=\d{10}$)/,'');
 var a=setE('#n','#en',n.length<2?'Please enter your full name.':'');
 var b=setE('#p','#ep',/^[6-9]\d{9}$/.test(digits)?'':'Enter a valid 10-digit Indian mobile number.');
 var c=setE('#e','#ee',/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(em)?'':'Enter a valid email address.');
 if(!(a&&b&&c)){var f=document.querySelector('[aria-invalid=true]');f&&f.focus();return}
 $('#gb').classList.add('loading');$('#gb').disabled=true;setTimeout(function(){if($('#gate').style.display!=='none')open_()},3500);
 setTimeout(function(){
  try{sessionStorage.setItem('sjm_in','1')}catch(x){}
  window.SJU={name:n,phone:digits,email:em};ls('sjm_user',JSON.stringify(window.SJU));
  if(COLLEGE.collectUrl){try{fetch(COLLEGE.collectUrl,{method:'POST',mode:'no-cors',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify(window.SJU)}).catch(function(){})}catch(x){}}
  open_();window.scrollTo(0,0);
 },900);
});
